INSERT INTO "Dokumen" ("id","studentId","kategori","tajuk","penggal","tahun","tarikh","status","kandungan","diterbitOlehId","createdAt","updatedAt") VALUES ('d_doc_050','st_mur_06','SIJIL','Sijil Penyertaan Pertandingan',NULL,2026,NOW() - INTERVAL '11 days','DITERBITKAN','# SIJIL PENYERTAAN KHEMAH IBADAH\n\n**SEKOLAH RENDAH AL FURQAN SHAH ALAM**\n\nDengan ini sesungguhnya mengurniakan Sijil Penyertaan Khemah Ibadah kepada:\n\n## Aisyah Nur binti Razif\n\n(No. Pendaftaran: AF2026006)\n\natas pencapaian cemerlang dalam Penyertaan Khemah Ibadah anjuran Sekolah Rendah Al Furqan Shah Alam pada tahun 2026.\n\n**Pengetua**\nSekolah Rendah Al Furqan Shah Alam','s_staff_02',NOW(),NOW());
INSERT INTO "Dokumen" ("id","studentId","kategori","tajuk","penggal","tahun","tarikh","status","kandungan","diterbitOlehId","createdAt","updatedAt") VALUES ('d_doc_051','st_mur_01','BORANG','Borang Kebenaran Aktiviti Kokurikulum',NULL,2026,NOW() - INTERVAL '4 days','DITERBITKAN','# BORANG KEBENARAN AKTIVITI KOKURIKULUM\n\n**SEKOLAH RENDAH AL FURQAN SHAH ALAM**\n\n## Maklumat Murid\n\n| Butiran | Maklumat |\n|---|---|\n| Nama | Ahmad Danish bin Razif |\n| No. Pendaftaran | AF2026001 |\n| Tahun | 1 |\n\nSaya mengaku bahawa maklumat di atas adalah benar.\n\n**Tandatangan Ibu Bapa / Penjaga:** _______________________\n\n**Tarikh:** _______________________','s_staff_02',NOW(),NOW());
INSERT INTO "Dokumen" ("id","studentId","kategori","tajuk","penggal","tahun","tarikh","status","kandungan","diterbitOlehId","createdAt","updatedAt") VALUES ('d_doc_052','st_mur_06','BORANG','Borang Maklum Balas Ibu Bapa',NULL,2026,NOW() - INTERVAL '3 days','DRAFT','# BORANG MAKLUM BALAS IBU BAPA\n\n**SEKOLAH RENDAH AL FURQAN SHAH ALAM**\n\n## Maklumat Murid\n\n| Butiran | Maklumat |\n|---|---|\n| Nama | Aisyah Nur binti Razif |\n| No. Pendaftaran | AF2026006 |\n| Tahun | 5 |\n\nSaya mengaku bahawa maklumat di atas adalah benar.\n\n**Tandatangan Ibu Bapa / Penjaga:** _______________________\n\n**Tarikh:** _______________________','s_staff_02',NOW(),NOW());
INSERT INTO "Dokumen" ("id","studentId","kategori","tajuk","penggal","tahun","tarikh","status","kandungan","diterbitOlehId","kelasId","createdAt","updatedAt") VALUES ('d_doc_053','st_mur_01','SURAT_EDARAN','Surat Edaran: Sambutan Maulidur Rasul',NULL,2026,NOW() - INTERVAL '5 days','DITERBITKAN','# SURAT EDARAN SEKOLAH\n\n**SEKOLAH RENDAH AL FURQAN SHAH ALAM**\nTahun Sekolah 2026\n\n## Sambutan Maulidur Rasul\n\nKepada ibu bapa / penjaga murid **1 Al Bukhari**, dimaklumkan perkara berikut:\n\n1. Tarikh: seperti tertera.\n2. Tempat: Sekolah Rendah Al Furqan Shah Alam.\n3. Kehadiran murid dan waris adalah diwajibkan.\n\nSekiranya terdapat pertanyaan, sila hubungi pejabat sekolah di 03-5512 3456.\n\nTerima kasih.\n\n**Pihak Sekolah**','s_staff_02','c_kelas_01',NOW(),NOW());
